<?php use VazinCMS\Security; ?><section class="title"><div><h1>محصولات</h1><p>تعرفه‌ها و محصولات قابل سفارش</p></div></section><?php if($error):?><div class="alert"><?=Security::e($error)?></div><?php endif;?><section class="split"><div class="panel"><h2>محصول جدید</h2><form method="post"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><label>نام<input name="name" required></label><label>شناسه انگلیسی<input name="slug" dir="ltr" placeholder="vpn-monthly" required></label><label>نوع<input name="type" value="service" required></label><label>قیمت<input type="number" name="price_amount" min="0" step="0.01" value="0" required></label><label>ارز<input name="currency" value="RUB" maxlength="8" required></label><label>دوره<select name="billing_cycle"><option value="one_time">یک‌بار</option><option value="monthly" selected>ماهانه</option><option value="quarterly">سه‌ماهه</option><option value="yearly">سالانه</option></select></label><label>توضیحات<textarea name="description" rows="4"></textarea></label><label class="check"><input type="checkbox" name="is_active" checked> فعال</label><button>ساخت محصول</button></form></div><div class="panel"><h2>فهرست محصولات</h2><div class="table"><table><thead><tr><th>محصول</th><th>نوع</th><th>قیمت</th><th>دوره</th><th>وضعیت</th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><b><?=Security::e($p['name'])?></b><br><code><?=Security::e($p['slug'])?></code></td><td><?=Security::e($p['type'])?></td><td><?=Security::e((string)$p['price_amount'])?> <?=Security::e($p['currency'])?></td><td><?=Security::e($p['billing_cycle'])?></td><td><span class="status <?=$p['is_active']?'active':'closed'?>"><?=$p['is_active']?'فعال':'غیرفعال'?></span></td></tr><?php endforeach;?></tbody></table></div></div></section>
